import{_ as t,o,c as a,ah as d}from"./chunks/framework.rk_qxSDs.js";const f=JSON.parse('{"title":"Assets Configuration","description":"Options of the assets plugin, from cache headers to the single-page-app fallback.","frontmatter":{"title":"Assets Configuration","description":"Options of the assets plugin, from cache headers to the single-page-app fallback.","relatedPlugins":[]},"headers":[],"relativePath":"assets/configuration.md","filePath":"assets/configuration.md","lastUpdated":1795602954000}'),c={name:"assets/configuration.md"};function s(r,e,i,n,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><code>assets(directory, options?)</code> takes the directory and one object, the <code>OptionsInput</code> type; every option is optional.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>scan</code></td><td><code>boolean</code></td><td><code>true</code></td><td>List the directory once and look files up in memory</td></tr><tr><td><code>cacheMaxAge</code></td><td><code>number | false</code></td><td><code>0</code></td><td><code>max-age</code> of the <code>Cache-Control</code> header, in seconds</td></tr><tr><td><code>cacheImmutable</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Add <code>immutable</code> to the <code>Cache-Control</code> header</td></tr><tr><td><code>fallback</code></td><td><code>boolean | string</code></td><td><code>false</code></td><td>File to serve when no file matches; <code>true</code> means the <code>index</code> file</td></tr><tr><td><code>fallbackIgnores</code></td><td><code>string | RegExp | Array&lt;string | RegExp&gt;</code></td><td>none</td><td>Paths that never get the fallback file</td></tr><tr><td><code>fallthrough</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Pass a request without a file on to the next handler; <code>false</code> answers <code>404</code></td></tr><tr><td><code>extensions</code></td><td><code>string[]</code></td><td><code>[&#39;html&#39;, &#39;htm&#39;]</code></td><td>Extensions tried after the path and for <code>index</code> files</td></tr><tr><td><code>dotFiles</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Serve paths with a segment that starts with <code>.</code></td></tr><tr><td><code>ignores</code></td><td><code>string | RegExp | Array&lt;string | RegExp&gt;</code></td><td><code>[]</code></td><td>Paths that are never served</td></tr><tr><td><code>resolve</code></td><td><code>(event) =&gt; Promise&lt;unknown&gt;</code></td><td>none</td><td>Builds the response for a request without a file</td></tr></tbody></table><p><code>OptionsInput</code> also has <code>directoryPath</code>; the <code>directory</code> argument always replaces it.</p><h3 id="scan" tabindex="-1"><code>scan</code> <a class="header-anchor" href="#scan" aria-label="Permalink to &quot;`scan`&quot;">​</a></h3><p>With <code>scan</code>, the plugin lists the directory when it is registered with <code>app.use()</code> (or when <code>createHandler()</code> or <code>createCoreHandler()</code> is called) and keeps each file&#39;s path and stats in memory, so a request does not touch the filesystem until the file is sent. The list is a snapshot: a file added later is not served, and a file removed later is still answered with <code>200</code>, whose body then fails while it is read. When the scan fails, for example because the directory does not exist, every request that reaches the plugin answers <code>500</code>.</p><p>Set <code>scan: false</code> for a directory that changes while the app runs; each request then checks the candidate paths on disk.</p><h3 id="cachemaxage" tabindex="-1"><code>cacheMaxAge</code> <a class="header-anchor" href="#cachemaxage" aria-label="Permalink to &quot;`cacheMaxAge`&quot;">​</a></h3><p>The <code>max-age</code> value in seconds. Every served file gets a <code>Cache-Control</code> header:</p><table tabindex="0"><thead><tr><th>Options</th><th><code>Cache-Control</code></th></tr></thead><tbody><tr><td>none, <code>0</code> or <code>false</code></td><td><code>public,max-age=0,must-revalidate</code></td></tr><tr><td><code>cacheMaxAge: 3600</code></td><td><code>public,max-age=3600</code></td></tr><tr><td><code>cacheImmutable: true</code></td><td><code>public,max-age=0,immutable</code></td></tr><tr><td><code>cacheMaxAge: 31536000, cacheImmutable: true</code></td><td><code>public,max-age=31536000,immutable</code></td></tr></tbody></table><p><code>false</code> does not remove the header; it is treated like <code>0</code>. <a href="/assets/recipes#cache-hashed-files">Cache Hashed Files</a> sets two policies for two folders.</p><h3 id="cacheimmutable" tabindex="-1"><code>cacheImmutable</code> <a class="header-anchor" href="#cacheimmutable" aria-label="Permalink to &quot;`cacheImmutable`&quot;">​</a></h3><p>Appends <code>immutable</code> in place of <code>must-revalidate</code>. Use it for content-hashed file names, whose content never changes under the same name.</p><h3 id="fallback" tabindex="-1"><code>fallback</code> <a class="header-anchor" href="#fallback" aria-label="Permalink to &quot;`fallback`&quot;">​</a></h3><p>The file served when no file matches, for a single-page app whose client-side router handles the path. <code>true</code> serves the <code>index</code> file of the directory (<code>index.html</code> with the default <code>extensions</code>), a string names a file, such as <code>&#39;index.html&#39;</code>.</p><p>The extension of the string is removed and <code>extensions</code> is tried again: <code>&#39;index.html&#39;</code> is looked up as <code>/index</code>, then <code>/index.html</code>. With <code>extensions: []</code>, the fallback file is not found. Without <a href="#fallbackignores"><code>fallbackIgnores</code></a>, every path without a file gets the fallback, also <code>/api/...</code> and <code>/missing.js</code>.</p><p>The <a href="https://routup.dev/examples/static-files" target="_blank" rel="noreferrer">Static Files</a> example on routup.dev serves a single-page app next to API routes.</p><h3 id="fallbackignores" tabindex="-1"><code>fallbackIgnores</code> <a class="header-anchor" href="#fallbackignores" aria-label="Permalink to &quot;`fallbackIgnores`&quot;">​</a></h3><p>Paths that do not get the fallback file; such a request goes on as if there were no fallback. Each entry becomes a case-insensitive regular expression: a string is compiled with the flag <code>i</code>, and the flags of a <code>RegExp</code> are replaced by <code>i</code>. The patterns are tested against the request path without the mount path, for example <code>&#39;^/api(/|$)&#39;</code>.</p><p>Setting <code>fallbackIgnores</code>, even to <code>[]</code>, also adds two patterns:</p><ul><li>a path that ends in a file name with an extension, such as <code>/app.js</code> or <code>/images/missing.png</code>, so a missing asset is not answered with the HTML shell</li><li><code>/.well-known</code>, or every path with a segment that starts with <code>.</code> when <a href="#dotfiles"><code>dotFiles</code></a> is <code>true</code></li></ul><h3 id="fallthrough" tabindex="-1"><code>fallthrough</code> <a class="header-anchor" href="#fallthrough" aria-label="Permalink to &quot;`fallthrough`&quot;">​</a></h3><p>With <code>true</code>, a request without a file, and without a response from <code>fallback</code> or <code>resolve</code>, goes on to the next handler. With <code>false</code>, the plugin answers <code>404</code> with an empty body and the handlers after it do not run for that request.</p><h3 id="extensions" tabindex="-1"><code>extensions</code> <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;`extensions`&quot;">​</a></h3><p>Tried after the plain path and for the <code>index</code> file of a directory: with the default, <code>/about</code> tries <code>/about</code>, <code>/about.html</code>, <code>/about.htm</code>, <code>/about/index.html</code> and <code>/about/index.htm</code>. A leading <code>.</code> is optional (<code>&#39;.html&#39;</code> or <code>&#39;html&#39;</code>).</p><h3 id="dotfiles" tabindex="-1"><code>dotFiles</code> <a class="header-anchor" href="#dotfiles" aria-label="Permalink to &quot;`dotFiles`&quot;">​</a></h3><p>With <code>false</code>, a path with a segment that starts with <code>.</code>, such as <code>/.env</code> or <code>/.git/config</code>, is not served; <code>/.well-known/...</code> still is. With <code>true</code>, every such path is served.</p><h3 id="ignores" tabindex="-1"><code>ignores</code> <a class="header-anchor" href="#ignores" aria-label="Permalink to &quot;`ignores`&quot;">​</a></h3><p>Paths that are never served. Each entry becomes a case-insensitive regular expression, as for <a href="#fallbackignores"><code>fallbackIgnores</code></a>, and is tested against the request path. A single string or <code>RegExp</code> passes the type check but is ignored; pass an array, for example <code>[/\\.map$/]</code> to keep source maps private.</p><p>The lookup also tries trailing parts of the path (<a href="/assets/#default-behaviour">Default Behaviour</a>), so an anchored pattern does not cover every path to a file: <code>[/^\\/secret/]</code> blocks <code>/secret.txt</code>, but <code>/x/secret.txt</code> still serves it. Use a pattern without the anchor, such as <code>/\\/secret/</code> or <code>/secret\\.txt$/</code>.</p><h3 id="resolve" tabindex="-1"><code>resolve</code> <a class="header-anchor" href="#resolve" aria-label="Permalink to &quot;`resolve`&quot;">​</a></h3><p>Called with the event when no file matches and the fallback did not apply, and also when sending the found file throws. Its return value is turned into a response like a handler&#39;s: an object becomes JSON, a string text. <code>undefined</code> gives no response, and <a href="#fallthrough"><code>fallthrough</code></a> decides what happens. <a href="/assets/recipes#answer-missing-files">Answer Missing Files</a> returns a JSON <code>404</code>.</p>',33)])])}const u=t(c,[["render",s]]);export{f as __pageData,u as default};
